from fractions import Fraction


def ruin_duration(k, N, p):
    """Expected number of 1-unit bets from k until 0 or N."""
    p = Fraction(p)
    q = 1 - p
    if p == q:
        return Fraction(k * (N - k))
    r = q / p
    return Fraction(k) / (q - p) - Fraction(N) / (q - p) * (1 - r ** k) / (1 - r ** N)
